import numpy as np
# The preceding confirmed custom step performs the source's bicubic,
# aspect-preserving, white-pad transform on each view and packs them.
# VGGT's mean/std operation is inside the ONNX model, not applied here.
def process(atlas, pair):
    images = np.asarray(atlas)
    if images.dtype != np.float32 or images.shape != (1, 3, 518, 1036):
        raise ValueError('VGGT images must be FP32 NCHW [1,3,518,1036]')
    if not np.isfinite(images).all() or images.min() < 0 or images.max() > 1:
        raise ValueError('VGGT RGB images must be finite in [0,1]')
    if len(pair['frames']) != 2: raise ValueError('Missing two-view source metadata')
    return {'p03o_images': np.ascontiguousarray(images), 'p03o_pair': pair}

import hashlib
from pathlib import Path
import numpy as np
import torch
import tensorrt as trt
model_path = Path('/home/atharv/spectra/repo/models/vggt-onnx/vggt.onnx')
weights_path = model_path.with_name('vggt.onnx.data')
engine_path = model_path.with_name('vggt.engine')
expected = {'pose_enc': (1, 2, 9), 'depth': (1, 2, 518, 518), 'depth_conf': (1, 2, 518, 518)}
def sha256(path):
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(8 * 1024 * 1024), b''): digest.update(chunk)
    return digest.hexdigest()
def create_engine():
    if not model_path.is_file() or not weights_path.is_file():
        raise FileNotFoundError('VGGT ONNX and its external vggt.onnx.data must remain together')
    logger = trt.Logger(trt.Logger.WARNING)
    if not engine_path.is_file():
        builder = trt.Builder(logger)
        network = builder.create_network(0)
        parser = trt.OnnxParser(network, logger)
        if not parser.parse_from_file(str(model_path)):
            errors = [str(parser.get_error(i)) for i in range(parser.num_errors)]
            raise RuntimeError('TensorRT ONNX parse failed; unsupported operations: ' + '; '.join(errors))
        config = builder.create_builder_config()
        config.set_memory_pool_limit(trt.MemoryPoolType.WORKSPACE, 1024 << 20)
        config.set_flag(trt.BuilderFlag.FP16)
        serialized = builder.build_serialized_network(network, config)
        if serialized is None: raise RuntimeError('TensorRT FP16 build failed; inspect unsupported operations and GPU out-of-memory diagnostics')
        engine_path.write_bytes(bytes(serialized))
    runtime = trt.Runtime(logger)
    engine = runtime.deserialize_cuda_engine(engine_path.read_bytes())
    if engine is None: raise RuntimeError('TensorRT engine deserialization failed on this GPU/runtime')
    names = [engine.get_tensor_name(i) for i in range(engine.num_io_tensors)]
    inputs = [n for n in names if engine.get_tensor_mode(n) == trt.TensorIOMode.INPUT]
    outputs = [n for n in names if engine.get_tensor_mode(n) == trt.TensorIOMode.OUTPUT]
    if inputs != ['images'] or set(outputs) != set(expected): raise ValueError('VGGT engine interface mismatch')
    if tuple(engine.get_tensor_shape('images')) != (1, 3, 518, 1036) or engine.get_tensor_dtype('images') != trt.float32:
        raise ValueError('TensorRT must expose FP32 [1,3,518,1036] input despite FP16 internal compute')
    context = engine.create_execution_context()
    if context is None: raise RuntimeError('TensorRT could not allocate an execution context; check GPU memory')
    return engine, context
# Initialize engine/context once per inference branch, not once per atlas.
engine, context = create_engine()
stream = torch.cuda.Stream()
model_hash = sha256(model_path)
weights_hash = sha256(weights_path)
engine_hash = sha256(engine_path)
def process(images):
    if not torch.cuda.is_available(): raise RuntimeError('TensorRT requires a working NVIDIA CUDA runtime')
    if images.dtype != np.float32 or images.shape != (1, 3, 518, 1036): raise ValueError('Invalid atlas')
    try:
        with torch.cuda.stream(stream):
            tensors = {'images': torch.from_numpy(np.ascontiguousarray(images)).to('cuda')}
            for name, shape in expected.items():
                if tuple(context.get_tensor_shape(name)) != shape: raise ValueError(f'Engine output shape differs: {name}')
                dtype = engine.get_tensor_dtype(name)
                if dtype not in (trt.float32, trt.float16): raise ValueError(f'Unsupported output dtype: {name}: {dtype}')
                tensors[name] = torch.empty(shape, device='cuda', dtype=torch.float32 if dtype == trt.float32 else torch.float16)
            for name, tensor in tensors.items():
                if not context.set_tensor_address(name, tensor.data_ptr()): raise RuntimeError(f'TensorRT rejected buffer: {name}')
            if not context.execute_async_v3(stream_handle=stream.cuda_stream): raise RuntimeError('TensorRT execution failed')
        stream.synchronize()
        result = {name: tensors[name].float().cpu().numpy() for name in expected}
    except (torch.cuda.OutOfMemoryError, MemoryError) as exc:
        raise RuntimeError('VGGT TensorRT inference ran out of GPU memory on the 4 GB target; no geometry was produced') from exc
    return {'p04o_pose': result['pose_enc'], 'p04o_depth': result['depth'], 'p04o_conf': result['depth_conf'], 'p04o_runtime': {'backend': 'tensorrt', 'internal_precision': 'fp16', 'io_precision': 'fp32', 'gpu': torch.cuda.get_device_name(), 'model_sha256': model_hash, 'external_weights_sha256': weights_hash, 'engine_sha256': engine_hash}}

import numpy as np
def process(pose_enc, depth, depth_conf, runtime, pair):
    shapes = {'pose_enc': (1, 2, 9), 'depth': (1, 2, 518, 518), 'depth_conf': (1, 2, 518, 518)}
    checked = {}
    for name, value in (('pose_enc', pose_enc), ('depth', depth), ('depth_conf', depth_conf)):
        value = np.asarray(value, dtype=np.float32)
        if value.shape != shapes[name] or not np.isfinite(value).all():
            raise ValueError(f'Invalid {name}: expected finite tensor {shapes[name]}, got {value.shape}')
        checked[name] = value
    if len(pair['frames']) != 2: raise ValueError('Missing source records for the two views')
    # No bounding-box parsing, class mapping, NMS, or confidence-as-probability threshold.
    return {'p05o_raw': {'pose_enc': checked['pose_enc'], 'depth': checked['depth'], 'depth_conf': checked['depth_conf'], 'runtime': runtime, 'pair': pair}}

from pathlib import Path
def process(manifest):
    if not manifest['ply_roundtrip_verified'] or not Path(manifest['ply']).is_file():
        raise RuntimeError('Cannot announce geometry before verified PLY exists')
    event = {'schema_version': 1, 'event': parameters['event'], 'action': parameters['action'],
             'pair_id': manifest['pair_id'], 'frames': manifest['frames'],
             'point_count': manifest['point_count'], 'ply': manifest['ply'],
             'hashes': manifest['hashes'], 'scale': manifest['scale']}
    return {'p08o_event': event}

from pathlib import Path
import cv2
destination = Path('/home/atharv/spectra/output/frames')
# Independent port events: an image arrives for every decoded frame;
# a manifest arrives only after a complete reconstruction.
frame_number = 0
def on_frame(frame):
    global frame_number
    destination.mkdir(parents=True, exist_ok=True)
    path = destination / f'{frame_number:06d}.png'
    if not cv2.imwrite(str(path), frame): raise RuntimeError(f'Failed to save frame: {path}')
    frame_number += 1
def on_manifest(manifest):
    ply = Path(manifest['ply'])
    if ply.parent != destination or not ply.is_file() or not manifest['ply_roundtrip_verified']:
        raise RuntimeError('Verified PLY is missing from the requested saved-images destination')
